-- FEC money for the look-alike / shared-treasurer committees: per-cycle totals, and how much reached candidates or other committees
SELECT CMTE_ID, COMMITTEE_NAME, COVERAGE_END_DATE, TOTAL_RECEIPTS, INDIVIDUAL_CONTRIBUTIONS, TOTAL_DISBURSEMENTS, CONTRIBUTIONS_TO_OTHER_COMMITTEES, INDEPENDENT_EXPENDITURES, PCT_DISBURSED_TO_OTHERS, CASH_CLOSE_OF_PERIOD, DEBTS_OWED_BY
FROM LIBRARY_MARTS.POLITICS.POLITICS__FED_FEC_PAC_SUMMARY
WHERE CMTE_ID IN ('C00822106','C00691329','C00469239','C00691949','C00784496','C00715573','C00667865','C00763979','C00669051','C00674267')
ORDER BY CMTE_ID, COVERAGE_END_DATE
